// Force-Directed Graph — Network, route: ref
// Source: force-directed-graph_2
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useRef } from 'react';
import * as d3 from 'd3';

// ---- inlined from forceGraph ----
type GraphNode = { id: string; group: string };
type GraphLink = { source: string; target: string; value: number };

const GROUP_NAMES = ['Runtime', 'Scales', 'Shapes', 'Layouts', 'Interaction', 'Color'];

/** Six communities of nine modules each; the first of every list is its hub. */
const MEMBERS: string[][] = [
  ['selection', 'transition', 'timer', 'dispatch', 'ease', 'interpolate', 'format', 'time-format', 'dsv'],
  ['scale-linear', 'scale-log', 'scale-pow', 'scale-time', 'scale-band', 'scale-point', 'scale-ordinal', 'scale-quantile', 'scale-sequential'],
  ['arc', 'line', 'area', 'pie', 'stack', 'symbol', 'curve', 'link-shape', 'radial-line'],
  ['force', 'hierarchy', 'tree', 'cluster', 'treemap', 'pack', 'partition', 'chord', 'sankey'],
  ['zoom', 'drag', 'brush', 'quadtree', 'polygon', 'contour', 'delaunay', 'voronoi', 'hexbin'],
  ['color', 'rgb', 'hsl', 'lab', 'hcl', 'scheme', 'interpolate-rgb', 'interpolate-hcl', 'legend']
];

/** Mulberry32. The graph must be byte-identical on every load, so never Math.random. */
function seeded(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const graphNodes: GraphNode[] = GROUP_NAMES.flatMap((group, g) =>
  MEMBERS[g].map((id) => ({ id, group }))
);

function buildLinks(): GraphLink[] {
  const random = seeded(20260813);
  const seen = new Set<string>();
  const links: GraphLink[] = [];

  const add = (source: string, target: string, value: number) => {
    const key = source < target ? `${source}|${target}` : `${target}|${source}`;
    if (source === target || seen.has(key)) return;
    seen.add(key);
    links.push({ source, target, value });
  };

  MEMBERS.forEach((members) => {
    const [hub, ...rest] = members;
    rest.forEach((id) => add(hub, id, 1 + Math.floor(random() * 4)));
    // Chords inside the community so it reads as a cluster rather than a star.
    for (let k = 0; k < 7; k++) {
      add(rest[Math.floor(random() * rest.length)], rest[Math.floor(random() * rest.length)], 1);
    }
  });

  // Hub-to-hub ring plus peripheral bridges: enough coupling to pull the communities
  // together without dissolving them.
  MEMBERS.forEach((members, g) => add(members[0], MEMBERS[(g + 1) % MEMBERS.length][0], 4));
  for (let k = 0; k < 12; k++) {
    const a = MEMBERS[Math.floor(random() * MEMBERS.length)];
    const b = MEMBERS[Math.floor(random() * MEMBERS.length)];
    add(a[1 + Math.floor(random() * 8)], b[1 + Math.floor(random() * 8)], 1);
  }

  return links;
}

const graphLinks: GraphLink[] = buildLinks();

type SimNode = d3.SimulationNodeDatum & { id: string; group: string; degree: number };
type SimLink = d3.SimulationLinkDatum<SimNode> & { value: number };

/** Reserved band at the top for the group legend; the simulation is centered below it. */
const LEGEND_HEIGHT = 26;
const SETTLE_TICKS = 600;
const LAYOUT_SEED = 424242;
const FORCE_SEED = 20260813;

/** Nodes tagged with their group, weighted links by node id, and the group ordering the legend follows. */
export type Data = {
  nodes: { id: string; group: string }[];
  links: { source: string; target: string; value: number }[];
  groups: string[];
};

const DEMO: Data = { nodes: graphNodes, links: graphLinks, groups: GROUP_NAMES };

function radiusOf(node: { degree: number }): number {
  return 3.5 + Math.sqrt(node.degree) * 1.7;
}

export default function ForceDirectedGraph({ data = DEMO, width }:
  { data?: Data; width: number }) {
  const ref = useRef<SVGSVGElement | null>(null);
  const height = Math.round(width * 0.62);

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>(data.groups, d3.schemeObservable10),
    [data]
  );

  // Fixed initial positions: one ring slot per community, jittered by a seeded generator.
  // d3-force only seeds a node itself when x is NaN, so these survive into the simulation.
  const seedNodes = useMemo<SimNode[]>(() => {
    const degree = d3.rollup(
      data.links.flatMap((l) => [l.source, l.target]),
      (v) => v.length,
      (id) => id
    );
    const random = seeded(LAYOUT_SEED);
    const centerY = LEGEND_HEIGHT + (height - LEGEND_HEIGHT) / 2;
    const ring = Math.min(width, height - LEGEND_HEIGHT) * 0.26;
    return data.nodes.map((node) => {
      const angle = (data.groups.indexOf(node.group) / data.groups.length) * 2 * Math.PI;
      return {
        ...node,
        degree: degree.get(node.id) ?? 1,
        x: width / 2 + Math.cos(angle) * ring + (random() - 0.5) * 50,
        y: centerY + Math.sin(angle) * ring + (random() - 0.5) * 50
      };
    });
  }, [data, width, height]);

  useEffect(() => {
    const element = ref.current;
    if (!element || width === 0) return;

    const svg = d3.select(element);
    svg.selectAll('*').remove(); // StrictMode runs this effect twice in development.

    // Copy so a re-run starts from the seed positions rather than the settled ones.
    const nodes: SimNode[] = seedNodes.map((n) => ({ ...n }));
    const links: SimLink[] = data.links.map((l) => ({ ...l }));
    const centerY = LEGEND_HEIGHT + (height - LEGEND_HEIGHT) / 2;

    const simulation = d3
      .forceSimulation<SimNode>(nodes)
      .randomSource(seeded(FORCE_SEED))
      .force(
        'link',
        d3
          .forceLink<SimNode, SimLink>(links)
          .id((d) => d.id)
          .distance(40)
          .strength(0.55)
      )
      .force('charge', d3.forceManyBody<SimNode>().strength(-170).distanceMax(420))
      .force('center', d3.forceCenter(width / 2, centerY))
      .force('collide', d3.forceCollide<SimNode>((d) => radiusOf(d) + 2))
      .stop();

    const legend = svg.append('g').attr('font-size', 11).attr('fill', 'var(--muted)');
    const slot = Math.min(126, width / data.groups.length);
    legend
      .selectAll('g')
      .data(data.groups)
      .join('g')
      .attr('transform', (_, i) => `translate(${8 + i * slot},16)`)
      .call((g) => g.append('circle').attr('r', 4).attr('fill', (d) => color(d)))
      .call((g) =>
        g
          .append('text')
          .attr('x', 10)
          .attr('dy', '0.32em')
          .text((d) => d)
      );

    const link = svg
      .append('g')
      // --line is nearly the background; edges carry the structure here, so lift them.
      .attr('stroke', 'var(--muted)')
      .attr('stroke-opacity', 0.4)
      .selectAll<SVGLineElement, SimLink>('line')
      .data(links)
      .join('line')
      .attr('stroke-width', (d) => Math.sqrt(d.value));

    const node = svg
      .append('g')
      .attr('stroke', 'var(--bg)')
      .attr('stroke-width', 1.5)
      .selectAll<SVGCircleElement, SimNode>('circle')
      .data(nodes)
      .join('circle')
      .attr('r', radiusOf)
      .attr('fill', (d) => color(d.group));

    node.append('title').text((d) => `${d.id} — ${d.group}`);

    // Clamping keeps every mark inside the viewBox, including after a drag reheats the layout.
    const ticked = () => {
      nodes.forEach((d) => {
        const r = radiusOf(d) + 1;
        d.x = Math.max(r, Math.min(width - r, d.x ?? width / 2));
        d.y = Math.max(LEGEND_HEIGHT + r, Math.min(height - r, d.y ?? centerY));
      });
      link
        .attr('x1', (d) => (d.source as SimNode).x ?? 0)
        .attr('y1', (d) => (d.source as SimNode).y ?? 0)
        .attr('x2', (d) => (d.target as SimNode).x ?? 0)
        .attr('y2', (d) => (d.target as SimNode).y ?? 0);
      node.attr('cx', (d) => d.x ?? 0).attr('cy', (d) => d.y ?? 0);
    };

    simulation.tick(SETTLE_TICKS);
    ticked();
    simulation.on('tick', ticked);

    const drag = d3
      .drag<SVGCircleElement, SimNode>()
      .on('start', (event, d) => {
        if (!event.active) simulation.alphaTarget(0.3).restart();
        d.fx = d.x;
        d.fy = d.y;
      })
      .on('drag', (event, d) => {
        d.fx = event.x;
        d.fy = event.y;
      })
      .on('end', (event, d) => {
        if (!event.active) simulation.alphaTarget(0);
        d.fx = null;
        d.fy = null;
      });
    node.call(drag).style('cursor', 'grab');

    return () => {
      simulation.on('tick', null).stop();
      node.on('.drag', null);
      svg.selectAll('*').remove();
    };
  }, [data, width, height, seedNodes, color]);

  if (width === 0) return null;

  return (
    <svg
      ref={ref}
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Force-directed graph of module dependencies across six library subsystems"
    />
  );
}
